package com.adesa.attendance.vendor;
import static com.adesa.attendance.vendor.VendorRules.*;
import com.lowagie.text.*;import com.lowagie.text.pdf.*;import java.io.*;import java.awt.Color;import java.util.*;
public final class VendorPdf {
 private VendorPdf(){}
 private static final Color NAVY=new Color(17,36,63),GOLD=new Color(178,133,38),MUTED=new Color(85,102,119);
 public static byte[] write(Map<String,Object> profile,byte[] signature){
 try{var output=new ByteArrayOutputStream();var document=new Document(PageSize.A4,45,45,65,55);PdfWriter.getInstance(document,output);byte[] fontBytes;try(var in=VendorPdf.class.getResourceAsStream("/vendor/body.ttf")){fontBytes=Objects.requireNonNull(in).readAllBytes();}BaseFont base=BaseFont.createFont("vendor-body.ttf",BaseFont.IDENTITY_H,BaseFont.EMBEDDED,true,fontBytes,null);Font normal=new Font(base,10,Font.NORMAL,NAVY),small=new Font(base,8,Font.NORMAL,MUTED),bold=new Font(base,10,Font.BOLD,NAVY);
 HeaderFooter header=new HeaderFooter(new Phrase("ADESA HOLDINGS  |  VENDOR ACQUISITION FORM  |  "+profile.get("reference"),small),false);header.setBorder(Rectangle.BOTTOM);header.setBorderColor(new Color(220,224,229));document.setHeader(header);HeaderFooter footer=new HeaderFooter(new Phrase("CONFIDENTIAL · Administrator access only  |  Page ",small),true);footer.setAlignment(Element.ALIGN_CENTER);footer.setBorder(Rectangle.TOP);document.setFooter(footer);document.addTitle("Vendor Acquisition Form - "+profile.get("reference"));document.open();
 var heading=new PdfPTable(new float[]{1,5});heading.setWidthPercentage(100);try(var in=VendorPdf.class.getResourceAsStream("/attendance/adesa-logo.png")){Image logo=Image.getInstance(Objects.requireNonNull(in).readAllBytes());logo.scaleToFit(58,58);PdfPCell cell=new PdfPCell(logo);cell.setBorder(0);heading.addCell(cell);}PdfPCell title=new PdfPCell();title.setBorder(0);title.addElement(new Paragraph(label(String.valueOf(profile.get("subsidiary"))),new Font(base,13,Font.BOLD,GOLD)));title.addElement(new Paragraph("Vendor Acquisition Form",new Font(base,22,Font.BOLD,NAVY)));heading.addCell(title);document.add(heading);
 var a=(Map<String,Object>)profile.get("answers");answer(document,"Application reference",profile.get("reference"),normal,bold);answer(document,"Signed submission date and time",a.get("submissionTime"),normal,bold);answer(document,"Signed submission version",a.get("formVersion")+" · Revision "+profile.get("revision"),normal,bold);answer(document,"Current administrator status (not an original vendor answer)",profile.get("status"),normal,bold);answer(document,"Current banking verification (not an original vendor answer)",profile.get("banking_status"),normal,bold);
 section(document,"1  Business and contact information",base);fields(document,a,new String[][]{{"businessName","Registered business name"},{"businessType","Business type"},{"businessTypeOther","Other business type — description"},{"address","Business address"},{"cac","CAC registration number, where applicable"},{"tin","Tax Identification Number, where applicable"},{"website","Website"},{"contactName","Primary contact full name"},{"contactPhone","Primary contact phone number"},{"contactEmail","Primary contact email address"},{"contactPosition","Primary contact position"}},normal,bold);
 section(document,"2  Goods, services and commercial terms",base);fields(document,a,new String[][]{{"categories","Vendor categories"},{"categoryOther","Other vendor category — description"},{"description","Description of products or services offered"},{"coverage","Coverage area"},{"paymentTerms","Payment terms offered"},{"paymentOther","Other payment terms — details"},{"leadDays","Typical delivery or service lead time in days"},{"warranty","Warranty or return policy, where applicable"}},normal,bold);
 section(document,"3  Banking and compliance",base);document.add(new Paragraph("Bank details will be independently verified before the first payment is made.",small));fields(document,a,new String[][]{{"bankName","Bank name"},{"accountName","Account name"},{"accountNumber","Account number"},{"bankFormat","Account format"},{"bankFormatDetails","Alternative account format — details"},{"conflict",CONFLICT},{"conflictDetails","Conflict of interest details, if Yes"}},normal,bold);
 answer(document,"Supporting documents",((java.util.List<?>)profile.get("documents")).stream().filter(v->!"SIGNATURE".equals(((Map<?,?>)v).get("category"))).map(v->{var d=(Map<?,?>)v;return d.get("category")+" — "+d.get("filename")+"\nUploaded: "+d.get("created_at")+"\nAvailability: "+(Boolean.TRUE.equals(d.get("ready"))?"Contents validated; stored privately":"Not available");}).reduce("",(x,y)->x+"\n\n"+y),normal,bold);
 section(document,"4  Data protection, declaration and signature",base);answer(document,"Data Protection Notice",a.get("privacyWording"),normal,bold);answer(document,"Declaration",a.get("declarationWording"),normal,bold);answer(document,"Declaration explicitly accepted",Boolean.TRUE.equals(a.get("declarationAccepted"))?"Yes":"No",normal,bold);answer(document,"Electronic signature consent",a.get("signatureConsentWording"),normal,bold);answer(document,"Electronic signature consent explicitly accepted",Boolean.TRUE.equals(a.get("signatureConsent"))?"Yes":"No",normal,bold);fields(document,a,new String[][]{{"signatoryName","Full name of authorised signatory"},{"signatoryPosition","Position of authorised signatory"},{"declarationDate","Date of declaration"},{"signatureMethod","Signature method"},{"signatureStyle","Selected signature style"}},normal,bold);
 PdfPTable signatureTable=new PdfPTable(1);signatureTable.setWidthPercentage(100);signatureTable.setKeepTogether(true);PdfPCell imageCell=new PdfPCell();imageCell.setBorderColor(new Color(220,224,229));imageCell.setPadding(12);imageCell.addElement(new Paragraph("Electronic signature",bold));Image image=Image.getInstance(signature);image.scaleToFit(340,100);imageCell.addElement(image);signatureTable.addCell(imageCell);document.add(signatureTable);document.add(new Paragraph("A generated signature is a visual representation of the typed name, not a verified handwritten signature. The signed submission is immutable; amendments require a new vendor confirmation and signature.",small));
 if(profile.get("notes") instanceof java.util.List<?> notes&&!notes.isEmpty()){section(document,"Administrator verification notes — added after submission",base);for(Object note:notes){var n=(Map<?,?>)note;answer(document,n.get("author")+" · "+n.get("createdAt"),n.get("body"),normal,bold);}}
 document.close();return output.toByteArray();}catch(Exception e){throw new IllegalStateException("Could not generate the confidential vendor application PDF",e);}
 }
 private static void section(Document d,String title,BaseFont font)throws DocumentException{Paragraph p=new Paragraph(title,new Font(font,13,Font.BOLD,NAVY));p.setSpacingBefore(22);p.setSpacingAfter(12);p.setKeepTogether(true);d.add(p);}
 private static void answer(Document d,String question,Object raw,Font normal,Font bold)throws DocumentException{String value=raw instanceof Collection<?> c?String.join(", ",c.stream().map(String::valueOf).toList()):raw==null?"":raw.toString().strip();if(value.isBlank())value="Not provided";Paragraph q=new Paragraph(question,bold);q.setSpacingBefore(10);q.setKeepTogether(true);d.add(q);Paragraph a=new Paragraph(value,normal);a.setLeading(15);a.setSpacingAfter(5);d.add(a);}
 private static void fields(Document d,Map<String,Object>a,String[][] fields,Font normal,Font bold)throws DocumentException{for(String[] f:fields){Object value=a.get(f[0]);boolean na=switch(f[0]){case "businessTypeOther"->!"Other".equals(a.get("businessType"));case "categoryOther"->!((java.util.List<?>)a.get("categories")).contains("Other");case "paymentOther"->!"Other".equals(a.get("paymentTerms"));case "conflictDetails"->!"Yes".equals(a.get("conflict"));case "bankFormatDetails"->!"ALTERNATIVE".equals(a.get("bankFormat"));case "signatureStyle"->!"TYPED".equals(a.get("signatureMethod"));default->false;};answer(d,f[1],na?"Not applicable":value,normal,bold);}}
}
